76	type MigrationJournalFile = {
77	  entries?: Array<{ idx?: number; tag?: string; when?: number }>;
78	};
79	
80	type JournalMigrationEntry = {
81	  fileName: string;
82	  folderMillis: number;
83	  order: number;
84	};
