86	async function listJournalMigrationEntries(): Promise<JournalMigrationEntry[]> {
87	  try {
88	    const raw = await readFile(MIGRATIONS_JOURNAL_JSON, "utf8");
89	    const parsed = JSON.parse(raw) as MigrationJournalFile;
90	    if (!Array.isArray(parsed.entries)) return [];
91	    return parsed.entries
92	      .map((entry, entryIndex) => {
93	        if (typeof entry?.tag !== "string") return null;
94	        if (typeof entry?.when !== "number" || !Number.isFinite(entry.when)) return null;
95	        const order = Number.isInteger(entry.idx) ? Number(entry.idx) : entryIndex;
96	        return { fileName: `${entry.tag}.sql`, folderMillis: entry.when, order };
97	      })
98	      .filter((entry): entry is JournalMigrationEntry => entry !== null);
99	  } catch {
100	    return [];
101	  }
102	}
