113	async function orderMigrationsByJournal(migrationFiles: string[]): Promise<string[]> {
114	  const journalEntries = await listJournalMigrationEntries();
115	  const orderByFileName = new Map(journalEntries.map((entry) => [entry.fileName, entry.order]));
116	  return [...migrationFiles].sort((left, right) => {
117	    const leftOrder = orderByFileName.get(left);
118	    const rightOrder = orderByFileName.get(right);
119	    if (leftOrder === undefined && rightOrder === undefined) return left.localeCompare(right);
120	    if (leftOrder === undefined) return 1;
121	    if (rightOrder === undefined) return -1;
122	    if (leftOrder === rightOrder) return left.localeCompare(right);
123	    return leftOrder - rightOrder;
124	  });
125	}
