127	type SqlExecutor = Pick<ReturnType<typeof postgres>, "unsafe">;
128	
129	async function runInTransaction(sql: SqlExecutor, action: () => Promise<void>): Promise<void> {
130	  await sql.unsafe("BEGIN");
131	  try {
132	    await action();
133	    await sql.unsafe("COMMIT");
134	  } catch (error) {
135	    try {
136	      await sql.unsafe("ROLLBACK");
137	    } catch {
138	      // Ignore rollback failures and surface the original error.
139	    }
140	    throw error;
141	  }
142	}
