144	async function latestMigrationCreatedAt(
145	  sql: SqlExecutor,
146	  qualifiedTable: string,
147	): Promise<number | null> {
148	  const rows = await sql.unsafe<{ created_at: string | number | null }[]>(
149	    `SELECT created_at FROM ${qualifiedTable} ORDER BY created_at DESC NULLS LAST LIMIT 1`,
150	  );
151	  const value = Number(rows[0]?.created_at ?? Number.NaN);
152	  return Number.isFinite(value) ? value : null;
153	}
