162	async function ensureMigrationJournalTable(
163	  sql: ReturnType<typeof postgres>,
164	): Promise<{ migrationTableSchema: string; columnNames: Set<string> }> {
165	  let migrationTableSchema = await discoverMigrationTableSchema(sql);
166	  if (!migrationTableSchema) {
167	    const drizzleSchema = quoteIdentifier("drizzle");
168	    const migrationTable = quoteIdentifier(DRIZZLE_MIGRATIONS_TABLE);
169	    await sql.unsafe(`CREATE SCHEMA IF NOT EXISTS ${drizzleSchema}`);
170	    await sql.unsafe(
171	      `CREATE TABLE IF NOT EXISTS ${drizzleSchema}.${migrationTable} (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at bigint)`,
172	    );
173	    migrationTableSchema = (await discoverMigrationTableSchema(sql)) ?? "drizzle";
174	  }
175	
176	  const columnNames = await getMigrationTableColumnNames(sql, migrationTableSchema);
177	  return { migrationTableSchema, columnNames };
178	}
