180	async function migrationHistoryEntryExists(
181	  sql: SqlExecutor,
182	  qualifiedTable: string,
183	  columnNames: Set<string>,
184	  migrationFile: string,
185	  hash: string,
186	): Promise<boolean> {
187	  const predicates: string[] = [];
188	  if (columnNames.has("hash")) predicates.push(`hash = ${quoteLiteral(hash)}`);
189	  if (columnNames.has("name")) predicates.push(`name = ${quoteLiteral(migrationFile)}`);
190	  if (predicates.length === 0) return false;
191	
192	  const rows = await sql.unsafe<{ one: number }[]>(
193	    `SELECT 1 AS one FROM ${qualifiedTable} WHERE ${predicates.join(" OR ")} LIMIT 1`,
194	  );
195	  return rows.length > 0;
196	}
