198	async function recordMigrationHistoryEntry(
199	  sql: SqlExecutor,
200	  qualifiedTable: string,
201	  columnNames: Set<string>,
202	  migrationFile: string,
203	  hash: string,
204	  folderMillis: number,
205	): Promise<void> {
206	  const insertColumns: string[] = [];
207	  const insertValues: string[] = [];
208	
209	  if (columnNames.has("hash")) {
210	    insertColumns.push(quoteIdentifier("hash"));
211	    insertValues.push(quoteLiteral(hash));
212	  }
213	  if (columnNames.has("name")) {
214	    insertColumns.push(quoteIdentifier("name"));
215	    insertValues.push(quoteLiteral(migrationFile));
216	  }
217	  if (columnNames.has("created_at")) {
218	    const latestCreatedAt = await latestMigrationCreatedAt(sql, qualifiedTable);
219	    const createdAt = latestCreatedAt === null
220	      ? normalizeFolderMillis(folderMillis)
221	      : Math.max(latestCreatedAt + 1, normalizeFolderMillis(folderMillis));
222	    insertColumns.push(quoteIdentifier("created_at"));
223	    insertValues.push(quoteLiteral(String(createdAt)));
224	  }
225	
226	  if (insertColumns.length === 0) return;
227	
228	  await sql.unsafe(
229	    `INSERT INTO ${qualifiedTable} (${insertColumns.join(", ")}) VALUES (${insertValues.join(", ")})`,
230	  );
231	}
