233	async function applyPendingMigrationsManually(
234	  url: string,
235	  pendingMigrations: string[],
236	): Promise<void> {
237	  if (pendingMigrations.length === 0) return;
238	
239	  const orderedPendingMigrations = await orderMigrationsByJournal(pendingMigrations);
240	  const journalEntries = await listJournalMigrationEntries();
241	  const folderMillisByFileName = new Map(
242	    journalEntries.map((entry) => [entry.fileName, normalizeFolderMillis(entry.folderMillis)]),
243	  );
244	
245	  const sql = createUtilitySql(url);
246	  try {
247	    const { migrationTableSchema, columnNames } = await ensureMigrationJournalTable(sql);
248	    const qualifiedTable = `${quoteIdentifier(migrationTableSchema)}.${quoteIdentifier(DRIZZLE_MIGRATIONS_TABLE)}`;
249	
250	    for (const migrationFile of orderedPendingMigrations) {
251	      const migrationContent = await readMigrationFileContent(migrationFile);
252	      const hash = createHash("sha256").update(migrationContent).digest("hex");
253	      const existingEntry = await migrationHistoryEntryExists(
254	        sql,
255	        qualifiedTable,
256	        columnNames,
257	        migrationFile,
258	        hash,
259	      );
260	      if (existingEntry) continue;
261	
262	      await runInTransaction(sql, async () => {
263	        for (const statement of splitMigrationStatements(migrationContent)) {
264	          await sql.unsafe(statement);
265	        }
266	
267	        await recordMigrationHistoryEntry(
268	          sql,
269	          qualifiedTable,
270	          columnNames,
271	          migrationFile,
272	          hash,
273	          folderMillisByFileName.get(migrationFile) ?? Date.now(),
274	        );
275	      });
276	    }
277	  } finally {
278	    await sql.end();
279	  }
280	}
