282	async function mapHashesToMigrationFiles(migrationFiles: string[]): Promise<Map<string, string>> {
283	  const mapped = new Map<string, string>();
284	
285	  await Promise.all(
286	    migrationFiles.map(async (migrationFile) => {
287	      const content = await readMigrationFileContent(migrationFile);
288	      const hash = createHash("sha256").update(content).digest("hex");
289	      mapped.set(hash, migrationFile);
290	    }),
291	  );
292	
293	  return mapped;
294	}
