408	async function migrationContentAlreadyApplied(
409	  sql: ReturnType<typeof postgres>,
410	  migrationContent: string,
411	): Promise<boolean> {
412	  const statements = splitMigrationStatements(migrationContent);
413	  if (statements.length === 0) return false;
414	
415	  for (const statement of statements) {
416	    const applied = await migrationStatementAlreadyApplied(sql, statement);
417	    if (!applied) return false;
418	  }
419	
420	  return true;
421	}
