423	async function loadAppliedMigrations(
424	  sql: ReturnType<typeof postgres>,
425	  migrationTableSchema: string,
426	  availableMigrations: string[],
427	): Promise<string[]> {
428	  const quotedSchema = quoteIdentifier(migrationTableSchema);
429	  const qualifiedTable = `${quotedSchema}.${quoteIdentifier(DRIZZLE_MIGRATIONS_TABLE)}`;
430	  const columnNames = await getMigrationTableColumnNames(sql, migrationTableSchema);
431	
432	  if (columnNames.has("name")) {
433	    const rows = await sql.unsafe<{ name: string }[]>(`SELECT name FROM ${qualifiedTable} ORDER BY id`);
434	    return rows.map((row) => row.name).filter((name): name is string => Boolean(name));
435	  }
436	
437	  if (columnNames.has("hash")) {
438	    const rows = await sql.unsafe<{ hash: string }[]>(`SELECT hash FROM ${qualifiedTable} ORDER BY id`);
439	    const hashesToMigrationFiles = await mapHashesToMigrationFiles(availableMigrations);
440	    const appliedFromHashes = rows
441	      .map((row) => hashesToMigrationFiles.get(row.hash))
442	      .filter((name): name is string => Boolean(name));
443	
444	    if (appliedFromHashes.length > 0) {
445	      // Best-effort: when all hashes resolve, this is authoritative.
446	      if (appliedFromHashes.length === rows.length) return appliedFromHashes;
447	
448	      // Partial hash resolution can happen when files have changed; return what we can trust.
449	      return appliedFromHashes;
450	    }
451	
452	    // Fallback only when hashes are unavailable/unresolved.
453	    if (columnNames.has("created_at")) {
454	      const journalEntries = await listJournalMigrationEntries();
455	      if (journalEntries.length > 0) {
456	        const lastDbRows = await sql.unsafe<{ created_at: string | number | null }[]>(
457	          `SELECT created_at FROM ${qualifiedTable} ORDER BY created_at DESC LIMIT 1`,
458	        );
459	        const lastCreatedAt = Number(lastDbRows[0]?.created_at ?? -1);
460	        if (Number.isFinite(lastCreatedAt) && lastCreatedAt >= 0) {
461	          return journalEntries
462	            .filter((entry) => availableMigrations.includes(entry.fileName))
463	            .filter((entry) => entry.folderMillis <= lastCreatedAt)
464	            .map((entry) => entry.fileName)
465	            .slice(0, rows.length);
466	        }
467	      }
468	    }
469	  }
470	
471	  const rows = await sql.unsafe<{ id: number }[]>(`SELECT id FROM ${qualifiedTable} ORDER BY id`);
472	  const journalMigrationFiles = await listJournalMigrationFiles();
473	  const appliedFromIds = rows
474	    .map((row) => journalMigrationFiles[row.id - 1])
475	    .filter((name): name is string => Boolean(name));
476	  if (appliedFromIds.length > 0) return appliedFromIds;
477	
478	  return availableMigrations.slice(0, Math.max(0, rows.length));
479	}
